/// <summary>
/// /// Indicates whether the flight is enabled by default.
/// </summary>
/// <returns>boolean</returns>
[Hookable(false)]
protected boolean isEnabledByDefault()
{
    return true;
}

/// <summary>
/// /// Returns the singleton instance of the flight.
/// </summary>
